const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000},reducedMotion:'no-preference'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');fs.mkdirSync('audit-screenshots',{recursive:true});for(const island of [0,1]){await p.evaluate(i=>DEUTSCH_JOURNEY.select(i),island);const n=island?8:10;if(await p.locator('.map-ambient').count()!==n)throw Error('Missing ambient effect for map stops');if(await p.locator('.map-ambience').getAttribute('aria-hidden')!=='true'||await p.locator('.map-ambience').evaluate(e=>getComputedStyle(e).pointerEvents)!=='none')throw Error('Decoration is not inert');const types=await p.locator('.map-ambient').evaluateAll(xs=>xs.map(e=>e.dataset.ambientEffect));if(new Set(types).size<(island?4:7))throw Error('Effects are not thematic');await p.locator('.expedition-board').scrollIntoViewIfNeeded();await p.waitForFunction(()=>document.querySelector('.expedition-board.motion-in-view'));if(await p.locator('.map-ambient i').first().evaluate(e=>getComputedStyle(e).animationPlayState)!=='running')throw Error('Visible effects paused');if(!await p.evaluate(()=>{const board=document.querySelector('.expedition-board');board.classList.remove('motion-in-view');const paused=getComputedStyle(document.querySelector('.map-ambient i')).animationPlayState==='paused';board.classList.add('motion-in-view');return paused}))throw Error('Map visibility pause does not cover particles');for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Map effects overflow '+width);if(width===390)await p.locator('.expedition-board').screenshot({path:'audit-screenshots/map-ambience-island-'+island+'.png'})}await p.locator('[data-motion-toggle]').click();if(await p.locator('.map-ambience').evaluate(e=>getComputedStyle(e).display)!=='none')throw Error('Motion off leaves particles');await p.locator('[data-motion-toggle]').click();await p.emulateMedia({reducedMotion:'reduce'});if(await p.locator('.map-ambience').evaluate(e=>getComputedStyle(e).display)!=='none')throw Error('Reduced motion leaves particles');await p.emulateMedia({reducedMotion:'no-preference'});await p.evaluate(()=>document.querySelector('[data-journey-lesson="0"]').click());if(await p.locator('.map-ambience').count())throw Error('Ambient map effects leaked into lesson');if(await p.locator('#alContinue').count()!==1)throw Error('Map effects blocked lesson');}if(errors.length)throw Error(errors.join(';'));console.log('PASS map ambience: 18 themed stop effects across two islands, inert layers, click-through, viewport pause, toggle/reduced motion, responsive layouts and lesson isolation');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
